CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK (role IN ('analyst','operator')), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE projects (id TEXT PRIMARY KEY, owner_id TEXT REFERENCES users(id), name TEXT NOT NULL, status TEXT NOT NULL, source_version_id TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE source_versions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), source_type TEXT NOT NULL, checksum TEXT NOT NULL, profile_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE graph_mappings (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), version INTEGER NOT NULL, mapping_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(project_id, version));
CREATE TABLE analysis_runs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), mapping_id TEXT REFERENCES graph_mappings(id), algorithm TEXT NOT NULL, config_json TEXT NOT NULL, status TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, finished_at TIMESTAMP);
CREATE TABLE job_events (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES analysis_runs(id), sequence INTEGER NOT NULL, event_type TEXT NOT NULL, payload TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(run_id, sequence));
CREATE TABLE exports (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES analysis_runs(id), format TEXT NOT NULL, object_key TEXT NOT NULL, expires_at TIMESTAMP NOT NULL);
